// Meta-Rückmeldung lesen (Stefan 18.10.2026): App und Art kommen aus dem Webhook, der ausgelöst hat; signed_request aus dem Formular
// (POST, application/x-www-form-urlencoded, laut Meta-Doku "Data Deletion Callback"). Geprüft (HMAC-SHA256 mit dem App-Geheimcode) wird nur in
// der Datenbank (meta_rueckmeldung); der Geheimcode kommt nie in diesen Ablauf. Hier nur Form und Länge. Ausführungsdaten werden nicht gespeichert.
const QUELLEN = [
  ['Facebook Löschanfrage', 'facebook', 'loeschung'], ['Facebook Abmeldung', 'facebook', 'abmeldung'],
  ['Instagram Löschanfrage', 'instagram', 'loeschung'], ['Instagram Abmeldung', 'instagram', 'abmeldung'],
  // Threads (Stefan 19.10.2026, Migration 53): Callback-URL löschen bzw. deinstallieren im Anwendungsfall "Auf Threads API zugreifen"
  ['Threads Löschanfrage', 'threads', 'loeschung'], ['Threads Abmeldung', 'threads', 'abmeldung'],
];
let app = '', art = '';
for (const q of QUELLEN) { if ($(q[0]).isExecuted) { app = q[1]; art = q[2]; } }
const b = $json.body;
let sr = '';
if (b && typeof b === 'object' && typeof b.signed_request === 'string') sr = b.signed_request;
else if (typeof b === 'string') {
  // Rohform (falls der Inhalt nicht als Formular gelesen wurde)
  const m = /(?:^|&)signed_request=([^&]*)/.exec(b);
  if (m) { try { sr = decodeURIComponent(m[1].replace(/\+/g, ' ')); } catch (e) { sr = ''; } }
}
sr = String(sr || '').trim();
if (sr.length > 8192 || !/^[A-Za-z0-9_-]+={0,2}\.[A-Za-z0-9_-]+={0,2}$/.test(sr)) sr = '';
return [{ json: { app, art, signed_request: sr } }];

parameters.query:
-- Meta-Rückmeldung (Stefan 18.10.2026, Vertrag Migration 50): Signatur prüfen (in der Datenbank, mit dem App-Geheimcode),
-- Accounts finden, trennen bzw. Löschung vormerken; Antwort für Meta in r.antwort ({url, confirmation_code} bzw. {ok:true}).
SELECT meta_rueckmeldung($1::text, $2::text, $3::text) AS r;

parameters.jsCode:
// Öffentliche Seiten der Meta-Apps (Stefan 18.10.2026): welche Seite (Webhook, der ausgelöst hat) und beim Löschstatus der Bestätigungscode.
// Der Code wird nur auf Buchstaben und Ziffern gekürzt; die Datenbank prüft das Format (16 Zeichen 0-9, A-F) und meldet Fehler verständlich.
const SEITEN = { 'Datenschutz': 'datenschutz', 'Datenlöschung': 'datenloeschung', 'Nutzungsbedingungen': 'nutzungsbedingungen', 'Löschstatus': 'status' };
let seite = 'datenschutz';
for (const n of Object.keys(SEITEN)) { if ($(n).isExecuted) seite = SEITEN[n]; }
const q = $json.query || {};
const roh = (typeof q.code === 'string' || typeof q.code === 'number') ? String(q.code) : '';
const code = seite === 'status' ? roh.replace(/[^0-9A-Za-z]/g, '').slice(0, 40) : '';
return [{ json: { seite, code } }];

// Öffentliche Seiten der Meta-Apps (Stefan 18.10.2026): Datenschutzhinweise, Anleitung zur Datenlöschung, Nutzungsbedingungen und Stand einer
// Löschanfrage. Ohne Anmeldung, öffentlich und für die Crawler von Meta erreichbar (Platform Terms 4.a), daher ohne "noindex".
// Texte kommen aus der Datenbank (meta_rechtstext, meta_loeschung_status), das Corporate Design aus CD 1. Solange die Texte nicht freigegeben
// sind (entwurf), steht oben ein Entwurfs-Hinweis und die Prüfstellen sind sichtbar markiert. Keine Namen von Talents auf diesen Seiten.
const CD = $('Corporate Design (CD 1)').first().json;
const A = $('Seite lesen').first().json;
const D = $('Seite laden').first().json.r || {};
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const txt = v => String(v ?? '').trim();
const PN = txt(D.produkt_name), ANB = txt(D.anbieter_name);
const L = D.links && typeof D.links === 'object' ? D.links : {};
const F = CD.farben || {}, AB = CD.abgeleitet || {};
const logo = (CD.logos || {}).logo_fuer_dunkel;
// Adressen im Text als Link (nur https), Satzzeichen am Ende gehören nicht zur Adresse
const mitLinks = t => String(t ?? '').split(/(https:\/\/[^\s<>"]+)/).map((teil, i) => {
  if (i % 2 === 0) return esc(teil);
  const m = /^(.*?)([.,;:)]*)$/.exec(teil);
  return '<a href="' + esc(m[1]) + '">' + esc(m[1]) + '</a>' + esc(m[2]);
}).join('');
const stil = `${CD.fontCss || ''}
:root { --dunkel:${F.dunkel}; --weiss:${F.textAufDunkel}; --akzent:${F.akzent}; --akzentDunkel:${F.akzentDunkel}; --hell:${F.hell}; --grau:${F.grau}; --warn:${F.warnung}; --linie:${AB.tabellenLinie}; }
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--hell); }
body { font-family: '${CD.schrift}', sans-serif; color: var(--dunkel); font-size: 15px; line-height: 1.55; min-height: 100vh; }
.leiste { background: var(--dunkel); color: var(--weiss); }
.leiste .innen { max-width: 760px; margin: 0 auto; height: 60px; padding: 0 16px; display: flex; align-items: center; gap: 12px; }
.leiste img { height: 22px; display: block; }
.leiste .name { font-weight: 800; font-size: 16px; }
.rahmen { max-width: 760px; margin: 0 auto; padding: 0 16px 48px; }
.seitenkopf { padding: 26px 0 18px; }
.seitenkopf h1 { margin: 0; font-size: 26px; font-weight: 800; }
.seitenkopf p { margin: 6px 0 0; color: var(--grau); font-size: 15px; }
.karte { background: #FFFFFF; border-radius: 12px; padding: 20px 18px; margin: 0 0 16px; box-shadow: 0 2px 10px rgba(23,29,35,.06); }
h2 { margin: 0 0 8px; font-size: 19px; font-weight: 800; }
p { margin: 0 0 10px; }
ul { margin: 0 0 10px; padding-left: 20px; }
li { margin: 4px 0; }
a { color: var(--akzentDunkel); word-break: break-word; }
.klein { font-size: 13px; color: var(--grau); }
.hinweis { border-radius: 9px; padding: 12px 14px; font-size: 14.5px; margin: 0 0 16px; }
.hinweis.ok { background: #EEF4E6; border-left: 4px solid var(--akzentDunkel); }
.hinweis.fehler { background: #FBEFEC; border-left: 4px solid var(--warn); }
.hinweis p:last-child { margin-bottom: 0; }
.entwurf { background: #FFF6DB; border-left: 4px solid #C99A00; border-radius: 9px; padding: 12px 14px; font-size: 14.5px; margin: 0 0 16px; }
.pruefen { background: #FFF6DB; border-radius: 7px; padding: 8px 10px; font-size: 13.5px; margin: 8px 0 0; }
.pruefen strong { color: #7A5D00; }
form.code { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 8px; }
form.code input { font: inherit; font-size: 16px; padding: 10px 12px; border: 1.5px solid var(--linie); border-radius: 9px; min-width: 0; flex: 1 1 220px; letter-spacing: .04em; }
.knopf { display: inline-block; font: inherit; font-weight: 700; font-size: 15px; padding: 11px 18px; border: 0; border-radius: 9px; background: var(--akzentDunkel); color: #FFFFFF; cursor: pointer; }
.knopf:focus-visible, form.code input:focus-visible { outline: 2px solid var(--akzent); outline-offset: 2px; }
.fuss { text-align: center; padding: 8px 0 0; }
.fuss a { margin: 0 6px; white-space: nowrap; }
@media (max-width: 560px) { .seitenkopf h1 { font-size: 23px; } .knopf { width: 100%; } }`;
const firma = ANB || PN;
const leiste = '<header class="leiste"><div class="innen">' + (logo ? '<img src="' + esc(logo) + '" alt="' + esc(firma) + '">' : '<span class="name">' + esc(firma) + '</span>') + '</div></header>';
const fussLinks = [['Datenschutz', L.datenschutz], ['Daten löschen', L.datenloeschung], ['Nutzungsbedingungen', L.nutzungsbedingungen],
  ['Stand einer Löschanfrage', L.status], ['Impressum', L.impressum]]
  .filter(x => typeof x[1] === 'string' && /^https:\/\//.test(x[1])).map(x => '<a href="' + esc(x[1]) + '">' + esc(x[0]) + '</a>').join(' ');
const fuss = '<p class="klein fuss">' + (PN ? esc(PN) + (ANB ? ' von ' + esc(ANB) : '') + '<br>' : '') + fussLinks + '</p>';
const huelle = (inhalt, titel) => '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">'
  + '<meta name="referrer" content="no-referrer"><title>' + esc(titel) + '</title><style>' + stil + '</style></head><body>'
  + leiste + '<main class="rahmen">' + inhalt + fuss + '</main></body></html>';
const kopf = (titel, unter) => '<div class="seitenkopf"><h1>' + esc(titel) + '</h1>' + (unter ? '<p>' + esc(unter) + '</p>' : '') + '</div>';
const titelVoll = t => t + (PN ? ' – ' + PN : '');

let html;
if (A.seite === 'status') {
  const gefunden = D.gefunden === true;
  const art = gefunden ? 'ok' : (D.code ? 'fehler' : '');
  const box = art ? '<div class="hinweis ' + art + '"><p><strong>' + esc(D.titel) + '</strong></p><p>' + esc(D.text) + '</p>'
    + (D.code ? '<p class="klein">Bestätigungscode: ' + esc(D.code) + '</p>' : '') + '</div>' : '<p>' + esc(D.text) + '</p>';
  const form = '<form class="code" method="get" action="' + esc(L.status || '') + '"><label class="klein" for="code" style="flex-basis:100%">Bestätigungscode</label>'
    + '<input id="code" name="code" autocapitalize="characters" autocomplete="off" spellcheck="false" maxlength="40" value="' + esc(gefunden ? D.code : '') + '" placeholder="z. B. 3F9A0C7B12E45D68">'
    + '<button class="knopf" type="submit">Stand anzeigen</button></form>';
  const kontakt = D.kontakt_email ? '<p class="klein">Fragen zur Löschung: <a href="mailto:' + esc(D.kontakt_email) + '">' + esc(D.kontakt_email) + '</a></p>' : '';
  html = huelle(kopf('Stand einer Löschanfrage', PN ? 'Löschung von Daten aus ' + PN : '') + '<section class="karte">' + box + form + kontakt + '</section>',
    titelVoll('Stand einer Löschanfrage'));
} else if (D.ok !== true) {
  html = huelle(kopf('Seite nicht gefunden', '') + '<section class="karte"><p>Diese Seite gibt es nicht.</p></section>', titelVoll('Seite nicht gefunden'));
} else {
  const entwurf = D.entwurf === true;
  const hinweis = entwurf ? '<div class="entwurf"><p><strong>Entwurf, noch nicht freigegeben.</strong></p><p>Dieser Text wird noch geprüft. '
    + 'Markierte Stellen ("Zu prüfen") sind offen.</p></div>' : '';
  const abschnitte = (Array.isArray(D.abschnitte) ? D.abschnitte : []).map(a => {
    const abs = (Array.isArray(a.absaetze) ? a.absaetze : []).filter(x => typeof x === 'string' && x.trim()).map(x => '<p>' + mitLinks(x) + '</p>').join('');
    const li = (Array.isArray(a.liste) ? a.liste : []).filter(x => typeof x === 'string' && x.trim()).map(x => '<li>' + mitLinks(x) + '</li>').join('');
    const pr = entwurf && typeof a.pruefen === 'string' && a.pruefen.trim() ? '<p class="pruefen"><strong>Zu prüfen:</strong> ' + esc(a.pruefen) + '</p>' : '';
    return '<section class="karte"><h2>' + esc(a.titel) + '</h2>' + abs + (li ? '<ul>' + li + '</ul>' : '') + pr + '</section>';
  }).join('');
  const stand = D.stand ? '<p class="klein">' + esc(D.stand) + '</p>' : '';
  html = huelle(kopf(txt(D.titel), txt(D.untertitel)) + hinweis + abschnitte + stand, titelVoll(txt(D.titel)));
}
return [{ json: { html } }];

parameters.query:
-- Meta-Rückmeldungen (Stefan 18.10.2026, Vertrag Migration 50): fällige Löschungen ausführen, Nachprüfen, Aufräumen (nur im echten Lauf);
-- liefert die offenen Meldungen an Admins. Testlauf (manuell): meta_lauf(false) ändert nichts.
SELECT meta_lauf($1::boolean) AS r;

parameters.jsCode:
// Meldungen zu Meta-Rückmeldungen (Stefan 18.10.2026): eine Chat-Nachricht je Meldung und Empfänger (Admins); Texte und Empfänger aus meta_lauf().
// Pflichtmeldung (Löschung bzw. Abmeldung über Meta), nicht abschaltbar. Chat-Layout: Titel fett mit Doppelpunkt, Inhalt darunter, keine Emojis.
// Testläufe (alles außer production) senden nichts und merken nichts; meta_lauf(false) hat dann auch nichts gelöscht.
const test = $execution.mode !== 'production';
const r = $input.first().json.r || {};
if (r.ok !== true) throw new Error('Meta-Rückmeldungen: ' + String(r.fehler || 'Der Lauf ist nicht lesbar.').slice(0, 200));
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '').trim();
const esc = v => ohneEmoji(v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const out = [];
for (const m of Array.isArray(r.meldungen) ? r.meldungen : []) {
  const id = Number(m && m.id);
  const art = String((m && m.art) || '');
  if (!(id > 0) || !['eingang', 'erledigt'].includes(art)) continue;
  const titel = ohneEmoji(m.titel).replace(/:\s*$/, '') + ':';
  const text = ohneEmoji(m.text);
  if (!text) continue;
  for (const e of Array.isArray(m.empfaenger) ? m.empfaenger : []) {
    const roomId = String((e && e.room_id) || '').trim();
    const userId = String((e && e.user_id) || '').trim();
    if (!roomId && !userId) continue;
    out.push({ json: { id, art, user_id: userId, room_id: roomId, text: titel + '\n' + text, html: '<strong>' + esc(titel) + '</strong><br>' + esc(text), test } });
  }
}
return out;

// Testlauf (Stefan 18.10.2026): zeigt, was gesendet würde; es wird nichts gesendet, nichts gemerkt und nichts gelöscht
return $input.all().map(i => ({ json: { vorschau: 'würde senden (Testlauf, nichts gesendet, nichts gemerkt)', an: i.json.user_id, room_id: i.json.room_id,
  id: i.json.id, art: i.json.art, text: i.json.text } }));

// Gesendet auswerten (Stefan 18.10.2026): eine Meldung gilt als verschickt, wenn sie mindestens einem Empfänger zugestellt wurde
// (erst nach dem Senden merken). Gelingt das Senden an niemanden, bleibt sie offen und wird beim nächsten Lauf erneut versucht.
const gesendet = $input.all();
const quelle = $('Testlauf?').all(1);
const gruppen = {};
gesendet.forEach((it, i) => {
  let q = quelle[i];
  if (quelle.length !== gesendet.length) {
    const p = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
    q = p && typeof p.item === 'number' ? quelle[p.item] : undefined;
  }
  if (!q || !q.json) return;
  const j = it.json || {};
  const ok = !j.error && j.ok !== false;
  const key = q.json.id + '|' + q.json.art;
  const g = gruppen[key] = gruppen[key] || { id: q.json.id, art: q.json.art, gesendet: 0, fehlgeschlagen: 0, test: q.json.test };
  if (ok) g.gesendet++; else g.fehlgeschlagen++;
});
return Object.keys(gruppen).map(k => gruppen[k]).filter(g => g.gesendet > 0 && g.test === false).map(g => ({ json: g }));

parameters.query:
-- Verbundene Accounts ohne meta_nutzer_id, höchstens 10 (Stefan 18.10.2026, Vertrag Migration 50). Enthält Zugangsschlüssel im Klartext:
-- dieser Ablauf speichert keine Ausführungsdaten.
SELECT meta_nutzer_id_liste() AS r;

parameters.jsCode:
// Meta-Nutzer-ID nachtragen (Stefan 18.10.2026, Vertrag Migration 50): verbundene Accounts ohne meta_nutzer_id (höchstens 10 je Lauf) aus
// meta_nutzer_id_liste(). Ohne diese ID kann eine Lösch- oder Abmeldemeldung von Meta dem Account nicht zugeordnet werden.
// Die Zugangsschlüssel stehen nur in diesem Lauf (Ausführungsdaten werden nicht gespeichert).
const r = $input.first().json.r || {};
if (r.ok !== true) throw new Error('Meta-Nutzer-ID nachtragen: ' + String(r.fehler || 'Die Liste ist nicht lesbar.').slice(0, 200));
return (Array.isArray(r.kanaele) ? r.kanaele : [])
  .filter(k => k && Number.isInteger(k.kanal_id) && /^https:\/\/graph\.(facebook|instagram)\.com\/v[0-9.]{1,6}\/me$/.test(String(k.adresse || ''))
    && typeof k.schluessel === 'string' && k.schluessel.length > 10)
  .map(k => ({ json: { kanal_id: k.kanal_id, adresse: k.adresse, felder: /^[a-z_,]{1,40}$/.test(String(k.felder || '')) ? k.felder : 'id', schluessel: k.schluessel } }));

// Antworten von /me auswerten (Stefan 18.10.2026): je Account die ID (Facebook: id; Instagram: id und user_id, auch im data-Array).
// Nur die IDs gehen an die Datenbank (meta_nutzer_id_setzen prüft bei Instagram, dass user_id zur gespeicherten Konto-ID passt).
// Fehlerhafte Antworten werden übersprungen und beim nächsten Lauf erneut versucht. Keine Schlüssel in der Ausgabe.
const ein = $('Nachtragen: Einträge').all();
const aus = $input.all();
const liste = [];
aus.forEach((it, i) => {
  let q = ein[i];
  if (ein.length !== aus.length) {
    const p = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
    q = p && typeof p.item === 'number' ? ein[p.item] : undefined;
  }
  if (!q || !q.json) return;
  const j = it.json || {};
  if (Number(j.statusCode) !== 200) return;
  let b = j.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
  if (!b || typeof b !== 'object') return;
  const d = Array.isArray(b.data) && b.data[0] && typeof b.data[0] === 'object' ? b.data[0] : b;
  const id = String(d.id ?? '');
  if (!/^[0-9]{1,30}$/.test(id)) return;
  const antwort = { id };
  if (d.user_id !== undefined && d.user_id !== null) antwort.user_id = String(d.user_id);
  liste.push({ kanal_id: q.json.kanal_id, antwort });
});
return [{ json: { daten: JSON.stringify(liste), anzahl: liste.length } }];
